window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4cdd3bc3c02b374a"]={"versions": [{"id": "FIG-4cdd3bc3c02b374a", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses des Funktionsschritts <code>ComputeCRC</code> im Rahmen des AUTOSAR E2E Profile 7m (Protect-, Forward- und Check-Funktionen). Der Kontext umfasst die End-to-End-Kommunikationsabsicherung (E2E-Protokoll) über 64-Bit-CRC-Prüfsummenberechnung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufende Funktionen / Kontexte:</strong> <code>E2E_P07mProtect()</code>, <code>E2E_P07mCheck()</code>, <code>E2E_P07mForward()</code>.</li>\n<li><strong>Lokale Variablen / Entitäten:</strong></li>\n<li><code>uint64 ComputedCRC</code>: 64-Bit-Ganzzahlwert zur Aufnahme des Zwischen- und Endergebnisses der CRC-Berechnung.</li>\n<li><code>Offset</code>: Anzahl der dem E2E-Header vorangehenden Nutzdatenbytes.</li>\n<li><code>Data</code>: Byte-Array (<code>&amp;Data[...]</code>), welches die zu schützenden Nutz- und Header-Daten enthält.</li>\n<li><code>Length</code>: Gesamtlänge der Daten.</li>\n<li><strong>Schnittstellenfunktion:</strong></li>\n<li><code>Crc_CalculateCRC64(Crc_DataPtr, Crc_Length, Crc_StartValue64, Crc_IsFirstCall)</code>: Berechnungsfunktion der AUTOSAR CRC-Bibliothek.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Startknoten führt zur Deklaration bzw. Bereitstellung der Variablen <code>uint64 ComputedCRC</code>.</li>\n<li><strong>Bedingte Verzweigung (<code>Offset &gt; 0</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong><code>[FALSE]</code>-Pfad (Offset gleich 0):</strong> Ein einzelner Aufruf von <code>Crc_CalculateCRC64</code> mit:</li>\n<li><code>Crc_DataPtr: &amp;Data[offset+8]</code></li>\n<li><code>Crc_Length: Length-Offset-8</code></li>\n<li><code>Crc_StartValue64: 0xFF'FF'FF'FF'FF'FF'FF'FF</code></li>\n<li><code>Crc_IsFirstCall: TRUE</code></li>\n<li><strong><code>[TRUE]</code>-Pfad (Offset größer als 0):</strong> Zweistufige CRC-Berechnung:</li>\n<li>Erster Schritt: Berechnung über die Bytes vor dem CRC-Feld via <code>Crc_CalculateCRC64(&amp;Data[0], Offset, 0xFF'FF'FF'FF'FF'FF'FF'FF, TRUE)</code>.</li>\n<li>Zweiter Schritt: Fortsetzung über die Bytes nach dem CRC-Feld via <code>Crc_CalculateCRC64(&amp;Data[offset+8], Length-Offset-8, ComputedCRC, FALSE)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung und Abschluss:</strong> Beide Zweige münden in einen Merge-Knoten, an dem <code>ComputedCRC</code> über die gesamten E2E-geschützten Daten berechnet vorliegt, gefolgt von <code>return</code> an den Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die CRC-Berechnung spart das 8-Byte lange CRC-Feld selbst (an Position <code>offset</code> bis <code>offset+7</code>) aus, weshalb die Berechnung nach dem CRC bei Index <code>offset+8</code> mit Restlänge <code>Length-Offset-8</code> ansetzt.</li>\n<li>Initialer Startwert für die CRC64-Berechnung ist <code>0xFFFFFFFFFFFFFFFF</code>.</li>\n<li>Bei zweigeteilter Berechnung (<code>Offset &gt; 0</code>) muss beim Folgeaufruf <code>Crc_IsFirstCall</code> zwingend auf <code>FALSE</code> gesetzt und das bisherige Zwischenergebnis <code>ComputedCRC</code> als Startwert übergeben werden.</li>\n</ul>"}, {"id": "FIG-659329451c90b518", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses des Funktionsschritts <code>ComputeCRC</code> im Rahmen des AUTOSAR E2E Profile 7m (Protect-, Forward- und Check-Funktionen). Der Kontext umfasst die End-to-End-Kommunikationsabsicherung (E2E-Protokoll) über 64-Bit-CRC-Prüfsummenberechnung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufende Funktionen / Kontexte:</strong> <code>E2E_P07mProtect()</code>, <code>E2E_P07mCheck()</code>, <code>E2E_P07mForward()</code>.</li>\n<li><strong>Lokale Variablen / Entitäten:</strong></li>\n<li><code>uint64 ComputedCRC</code>: 64-Bit-Ganzzahlwert zur Aufnahme des Zwischen- und Endergebnisses der CRC-Berechnung.</li>\n<li><code>Offset</code>: Anzahl der dem E2E-Header vorangehenden Nutzdatenbytes.</li>\n<li><code>Data</code>: Byte-Array (<code>&amp;Data[...]</code>), welches die zu schützenden Nutz- und Header-Daten enthält.</li>\n<li><code>Length</code>: Gesamtlänge der Daten.</li>\n<li><strong>Schnittstellenfunktion:</strong></li>\n<li><code>Crc_CalculateCRC64(Crc_DataPtr, Crc_Length, Crc_StartValue64, Crc_IsFirstCall)</code>: Berechnungsfunktion der AUTOSAR CRC-Bibliothek.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Startknoten führt zur Deklaration bzw. Bereitstellung der Variablen <code>uint64 ComputedCRC</code>.</li>\n<li><strong>Bedingte Verzweigung (<code>Offset &gt; 0</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong><code>[FALSE]</code>-Pfad (Offset gleich 0):</strong> Ein einzelner Aufruf von <code>Crc_CalculateCRC64</code> mit:</li>\n<li><code>Crc_DataPtr: &amp;Data[8]</code></li>\n<li><code>Crc_Length: Length-8</code></li>\n<li><code>Crc_StartValue64: 0xFF'FF'FF'FF'FF'FF'FF'FF</code></li>\n<li><code>Crc_IsFirstCall: TRUE</code></li>\n<li><strong><code>[TRUE]</code>-Pfad (Offset größer als 0):</strong> Zweistufige CRC-Berechnung:</li>\n<li>Erster Schritt: Berechnung über die Bytes vor dem CRC-Feld via <code>Crc_CalculateCRC64(&amp;Data[0], Offset, 0xFF'FF'FF'FF'FF'FF'FF'FF, TRUE)</code>.</li>\n<li>Zweiter Schritt: Fortsetzung über die Bytes nach dem CRC-Feld via <code>Crc_CalculateCRC64(&amp;Data[offset+8], Length-Offset-8, ComputedCRC, FALSE)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung und Abschluss:</strong> Beide Zweige münden in einen Merge-Knoten, an dem <code>ComputedCRC</code> über die gesamten E2E-geschützten Daten berechnet vorliegt, gefolgt von <code>return</code> an den Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die CRC-Berechnung spart das 8-Byte lange CRC-Feld selbst (an Position <code>offset</code> bis <code>offset+7</code>) aus, weshalb die Berechnung nach dem CRC bei Index <code>offset+8</code> mit Restlänge <code>Length-Offset-8</code> ansetzt.</li>\n<li>Initialer Startwert für die CRC64-Berechnung ist <code>0xFFFFFFFFFFFFFFFF</code>.</li>\n<li>Bei zweigeteilter Berechnung (<code>Offset &gt; 0</code>) muss beim Folgeaufruf <code>Crc_IsFirstCall</code> zwingend auf <code>FALSE</code> gesetzt und das bisherige Zwischenergebnis <code>ComputedCRC</code> als Startwert übergeben werden.</li>\n</ul>"}], "trans": [{"from": "FIG-4cdd3bc3c02b374a", "to": "FIG-659329451c90b518", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Funktionsaufruf im linken Zweig (<code>[FALSE]</code>): <code>Crc_DataPtr: &amp;Data[offset+8]</code> und <code>Crc_Length: Length-Offset-8</code> wurden zu <code>&amp;Data[8]</code> und <code>Length-8</code> vereinfacht (bei <code>Offset == 0</code>).</li>\n<li>Verweisziffer im Kopfbereich des Begleittextes: Querverweis auf Bildnummerierung angepasst.</li>\n</ul>"}]};
